  {
    path: 'profile',
    component: ProfileComponent,
    guards: [AuthGuard] // AuthGuard is a class, allowed because of 'any'
  }
];

// After (Angular 20)
export const authGuard: CanActivateFn = () => inject(MyService).canActivate();

const routes: Routes = [
  {
    path: 'profile',
    component: ProfileComponent,
    guards: [authGuard] // Function, strictly typed
  }
];
```
